use vstd::prelude::*;

verus! {

    /// Given two vectors `arr1` and `arr2` of equal length,
    /// returns a new vector `res` such that
    ///   for all valid indices `i`, res[i] == arr1[i] % arr2[i].
    /// 
    /// Assumptions:
    ///  1. arr1.len() == arr2.len()
    ///  2. For all i < arr2.len(), arr2[i] != 0
    ///  3. For all i < arr1.len(), (arr1[i] % arr2[i]) fits in a signed 32‐bit integer
    fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32>
        requires
            arr1.len() == arr2.len(),
            forall |i: usize| i < arr1.len() ==> arr2[i] != 0,
            forall |i: usize| i < arr1.len() ==> (arr1[i] % arr2[i]) <= (i32::MAX as u32),
        ensures
            |res: &Vec<u32>| res.len() == arr1.len()
                         && forall |i: usize| i < arr1.len() ==> res[i] == arr1[i] % arr2[i],
    {
        let n = arr1.len();
        let mut res: Vec<u32> = Vec::new();
        let mut idx: usize = 0;
        while idx < n
            invariant
                idx <= n,
                res.len() == idx,
                forall |j: usize| j < idx ==> res[j] == arr1[j] % arr2[j],
            decreases n - idx,
        {
            // safe to index because idx < n == arr1.len() == arr2.len()
            let r: u32 = arr1[idx] % arr2[idx];
            // r is within signed 32‐bit range by precondition
            res.push(r);
            idx = idx + 1;
        }
        res
    }

} // end verus! block

